window.PYQ_DATA.add({"id":"px-ncert11-bio-biomolecules","kind":"practice","exam":"NEET","year":null,"title":"Biomolecules · Practice","chapter":"Biomolecules","subject":"Biology","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","marking":{"mcq":[4,-1]},"rules":{},"note":"","questions":[{"id":"NCERT11-BIO-BIOMOLECULES-001","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":1,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements is correct?","image":"","options":["Every biological catalyst known is a protein, without exception.","Some nucleic acids behave like enzymes and are called ribozymes.","Melting of ice into water is a chemical reaction because the state of matter changes.","Inorganic catalysts are damaged at temperatures above about 40°C."],"optionsInImage":false,"answer":["2"],"explanation":"Almost all enzymes are proteins, but ribozymes are catalytic nucleic acids. Melting is a physical change because no bonds are broken or formed. It is enzymes, not inorganic catalysts, that get damaged at high temperatures.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-002","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":2,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements are correct?\n(i) Cytosine, uracil and thymine are substituted pyrimidines.\n(ii) Ribose is a monosaccharide pentose.\n(iii) The nucleic acid containing ribose is called deoxyribonucleic acid.\n(iv) Guanylic acid is a nucleoside.\n(v) Nucleic acids like DNA and RNA consist of nucleotides only.\n(vi) A nucleotide has three chemically distinct components: a heterocyclic compound, a monosaccharide and a phosphate.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (i), (ii), (v) and (vi) are correct. Statement (iii) is wrong because the nucleic acid containing ribose is RNA; DNA contains 2'-deoxyribose. Statement (iv) is wrong because guanylic acid is a nucleotide; guanosine is the nucleoside.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-003","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":3,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (category of secondary metabolite) with List-II (example).\nList-I:\nA. Toxin\nB. Lectin\nC. Drug\nD. Pigment\nList-II:\nI. Concanavalin A\nII. Vinblastin\nIII. Abrin\nIV. Anthocyanin\nChoose the correct option.","image":"","options":["A-III, B-I, C-II, D-IV","A-I, B-III, C-II, D-IV","A-III, B-II, C-I, D-IV","A-II, B-I, C-III, D-IV"],"optionsInImage":false,"answer":["1"],"explanation":"Abrin is a toxin, concanavalin A is a lectin, vinblastin is a drug and anthocyanin is a pigment. The common trap is swapping abrin and concanavalin A, since both are plant proteins.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-004","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":4,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The complex polysaccharide chitin is a major component of which of the following?","image":"","options":["Cell wall of higher plants","Exoskeleton of arthropods","Storage granules of animal liver","Cotton fibre"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT gives chitin as the complex polysaccharide of arthropod exoskeletons. Plant cell walls and cotton are made of cellulose, and liver stores glycogen.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-005","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":5,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In proteinaceous amino acids, the R group differs from one amino acid to another. Which of the following is the R group of serine?","image":"","options":["Hydrogen","Methyl group","Hydroxymethyl group","Carboxyl group"],"optionsInImage":false,"answer":["3"],"explanation":"Serine carries a hydroxymethyl ($-CH_2OH$) group as its R group. A hydrogen R group gives glycine and a methyl R group gives alanine, which are the common confusions.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-006","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":6,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Without any enzyme, about 200 molecules of $H_2CO_3$ form from $CO_2$ and water in one hour. With carbonic anhydrase, about 600,000 molecules form every second. By roughly what factor has the enzyme increased the rate?","image":"","options":["About $10^{3}$ times","About $10^{5}$ times","About $10^{7}$ times","About $10^{9}$ times"],"optionsInImage":false,"answer":["3"],"explanation":"The catalysed rate per hour is $6\\times10^{5}\\times3600 \\approx 2.16\\times10^{9}$ molecules. Dividing by 200 gives about $1.08\\times10^{7}$, i.e., roughly 10 million times. The trap is comparing 600,000 per second directly with 200 per hour without converting the units.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-007","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":7,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"An enzyme solution is kept at a temperature well below its optimum. What happens to the enzyme?","image":"","options":["It is permanently denatured","It stays in a temporarily inactive state and is preserved","Its activity rises above that at the optimum temperature","It loses its primary structure"],"optionsInImage":false,"answer":["2"],"explanation":"Low temperature keeps an enzyme temporarily inactive while preserving it, so activity returns on warming. Permanent loss of activity through denaturation is caused by high temperature, not low temperature.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-008","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":8,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"According to NCERT's comparison of elements in non-living and living matter, which element makes up about 27.7% of the weight of the earth's crust but is negligible in the human body?","image":"","options":["Calcium","Silicon","Sodium","Magnesium"],"optionsInImage":false,"answer":["2"],"explanation":"Silicon is 27.7% of the earth's crust but negligible in the human body. Ca, Na and Mg are present in both, although they are less abundant in the body than in the crust.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-009","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":9,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about enzyme cofactors are correct?\n(i) The protein portion of an enzyme that needs a cofactor is called the apoenzyme.\n(ii) Prosthetic groups are organic compounds tightly bound to the apoenzyme.\n(iii) Haem is the prosthetic group of peroxidase and catalase and is part of their active site.\n(iv) Coenzymes such as NAD and NADP contain the vitamin niacin.\n(v) An enzyme keeps its full catalytic activity even after its cofactor is removed.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (i) to (iv) agree with NCERT, so four statements are correct. Statement (v) is false: catalytic activity is lost when the cofactor is removed, which shows that cofactors are essential for catalysis.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-010","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":10,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The primary structure of a protein molecule has","image":"","options":["Two ends","One end","Three ends","No ends"],"optionsInImage":false,"answer":["1"],"explanation":"The primary structure is a linear chain of amino acids. It therefore has two ends: the N-terminal amino acid at one end and the C-terminal amino acid at the other.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q13)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-011","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":11,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"An aminoacid under certain conditions have both positive and negative charges simultaneously in the same molecule. Such a form of aminoacid is called","image":"","options":["Acidic form","Basic form","Aromatic form","Zwitterionic form"],"optionsInImage":false,"answer":["4"],"explanation":"Depending on pH, an amino acid can exist as a zwitterion. In this form the amino group is protonated (positive) and the carboxyl group is ionised (negative) at the same time.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q4)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-012","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":12,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Based on the comparison of earth's crust and the human body, and on the average composition of cells, how many of the following statements are correct?\n(i) The relative abundance of carbon and hydrogen is higher in living tissue than in earth's crust.\n(ii) Silicon is a major component of earth's crust but is negligible in the human body.\n(iii) Oxygen has the highest percentage by weight in both earth's crust and the human body.\n(iv) After water, proteins form the largest share of total cellular mass.\n(v) Nucleic acids make up a smaller share of cellular mass than carbohydrates.","image":"","options":["4","3","5","2"],"optionsInImage":false,"answer":["1"],"explanation":"Statements (i) to (iv) are correct (oxygen is 46.6% of the crust and 65% of the body; proteins are 10–15% of the cell). Statement (v) is false because nucleic acids (5–7%) exceed carbohydrates (3%) in cellular mass.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-013","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":13,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"When you take cells or tissue pieces and grind them with an acid in a mortar and pestle, all the small biomolecules dissolve in the acid. Proteins, polysaccharides and nucleic acids are insoluble in mineral acid and get precipitated. The acid soluble compounds include aminoacids, nucleosides, small sugars etc. When one adds a phosphate group to a nucleoside, one gets another acid soluble biomolecule called","image":"","options":["Nitrogen base","Adenine","Sugar phosphate","Nucleotide"],"optionsInImage":false,"answer":["4"],"explanation":"A nucleoside is a nitrogenous base attached to a sugar. Adding a phosphate group to it gives a nucleotide.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q6)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-014","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":14,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A graph plots the velocity of an enzymatic reaction (y-axis) against substrate concentration [S] (x-axis). The curve rises and then levels off at a maximum velocity. What is the substrate concentration at which the velocity equals half of this maximum called?","image":"","options":["$V_{max}$","Optimum concentration","Activation energy","$K_m$"],"optionsInImage":false,"answer":["4"],"explanation":"In Figure 9.5(c), the [S] value corresponding to $\\frac{V_{max}}{2}$ is marked as $K_m$. $V_{max}$ is the plateau velocity itself, not a substrate concentration.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-015","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":15,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In an enzyme, the 'active site' is best described as:","image":"","options":["A crevice or pocket formed by the folded chain, into which the substrate fits","The N-terminal amino acid of the polypeptide chain","A non-protein part that binds loosely to the enzyme only during catalysis","The straight part of the polypeptide that forms the primary structure"],"optionsInImage":false,"answer":["1"],"explanation":"When the polypeptide folds into its tertiary structure, the chain criss-crosses and forms pockets. One such pocket, where the substrate binds, is the active site. The other options describe the primary structure, the N-terminus and co-enzymes.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-016","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":16,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"An enzyme solution is kept at a temperature much lower than its optimum temperature. What is the most likely effect on the enzyme?","image":"","options":["It is permanently denatured and loses activity irreversibly","Its activity increases above the optimum level","It is preserved in a temporarily inactive state","Its active site is converted into a prosthetic group"],"optionsInImage":false,"answer":["3"],"explanation":"Low temperature only puts the enzyme into a temporarily inactive state. High temperature is different: it denatures the protein and destroys its activity. Do not confuse low-temperature inactivation with heat denaturation.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-017","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":17,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (cell component) with List-II (approximate % of total cellular mass):\nList-I\nA. Water\nB. Proteins\nC. Nucleic acids\nD. Lipids\nList-II\n(i) 2\n(ii) 5-7\n(iii) 10-15\n(iv) 70-90","image":"","options":["A-(iv), B-(ii), C-(iii), D-(i)","A-(iii), B-(iv), C-(ii), D-(i)","A-(iv), B-(iii), C-(ii), D-(i)","A-(iv), B-(iii), C-(i), D-(ii)"],"optionsInImage":false,"answer":["3"],"explanation":"Water is 70-90%, proteins 10-15%, nucleic acids 5-7% and lipids about 2% of cellular mass. A common mistake is to swap proteins and nucleic acids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-018","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":18,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I:\n(A) Cellulose\n(B) Glycogen\n(C) Inulin\n(D) Chitin\nList-II:\n(I) Polymer of fructose\n(II) Contains amino-sugars; found in arthropod exoskeleton\n(III) Homopolymer of glucose forming plant cell walls\n(IV) Storage polysaccharide of animals","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-II, D-I","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"The correct pairs are:\n- Cellulose is the glucose homopolymer of plant cell walls.\n- Glycogen is the animal storage variant.\n- Inulin is a fructose polymer.\n- Chitin is built from amino-sugars and forms arthropod exoskeletons.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-019","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":19,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Enzymes isolated from organisms living in hot vents and sulphur springs retain their catalytic power at temperatures up to 80–90°C.\nReason (R): Inorganic catalysts work efficiently at high temperatures and high pressures.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["2"],"explanation":"Both statements are true. However, the stability of enzymes from thermophiles comes from their own thermostable nature, not from any property of inorganic catalysts. So R does not explain A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-020","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":20,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Proteins perform many physiological functions. For example, some functions as enzymes. Which of the following represents an additional function that some proteins discharge?","image":"","options":["Antibiotics","Pigment conferring colour to skin","Pigments making colours of flowers","Hormones"],"optionsInImage":false,"answer":["4"],"explanation":"Some proteins act as hormones; insulin is an example. Skin pigment (melanin), flower pigments and most antibiotics are not proteins.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q10)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-021","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":21,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following pairs of a protein and its function is correctly matched?","image":"","options":["Trypsin – Hormone","Collagen – Enables glucose transport into cells","GLUT-4 – Enables glucose transport into cells","Insulin – Fights infectious agents"],"optionsInImage":false,"answer":["3"],"explanation":"GLUT-4 enables glucose to enter cells. Trypsin is an enzyme, collagen forms intercellular ground substance, insulin is a hormone, and antibodies fight infectious agents.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-022","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":22,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I\n(A) Wet weight\n(B) Dry weight\n(C) Ash\n(D) Acid-insoluble fraction\nList-II\n(I) Mass left after all water evaporates from the tissue\n(II) Material retained on cheesecloth after straining the trichloroacetic acid slurry\n(III) Mass of fresh tissue taken before drying\n(IV) Residue left after the tissue is fully burnt\nChoose the correct answer.","image":"","options":["A-III, B-I, C-IV, D-II","A-I, B-III, C-IV, D-II","A-III, B-I, C-II, D-IV","A-IV, B-I, C-III, D-II"],"optionsInImage":false,"answer":["1"],"explanation":"Fresh tissue mass is the wet weight, and the mass after evaporating water is the dry weight. The residue after complete burning is ash, and the retentate on the cloth is the acid-insoluble fraction.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-023","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":23,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Collagen is the most abundant protein in the animal world.\nStatement II: Receptor proteins function in sensory reception such as smell, taste and hormone reception.\nChoose the correct option:","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT states that collagen is the most abundant protein in the animal world, which makes Statement I correct. It also lists receptors as proteins for sensory reception such as smell, taste and hormones, which makes Statement II correct.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-024","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":24,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"To study the organic compounds of a living tissue, the tissue is first ground with a mortar and pestle in which of the following chemicals?","image":"","options":["Trichloroacetic acid ($Cl_3CCOOH$)","Hydrochloric acid ($HCl$)","Sodium hydroxide ($NaOH$)","Ethanol ($C_2H_5OH$)"],"optionsInImage":false,"answer":["1"],"explanation":"NCERT describes grinding living tissue such as a vegetable or liver in trichloroacetic acid to get a thick slurry. The slurry is then strained to separate the acid-soluble and acid-insoluble fractions.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-025","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":25,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Of the four classes of organic compounds in the acid-insoluble fraction, which one is NOT a polymeric substance?","image":"","options":["Proteins","Nucleic acids","Polysaccharides","Lipids"],"optionsInImage":false,"answer":["4"],"explanation":"Proteins, nucleic acids and polysaccharides are polymers with molecular weights of 10,000 Da and above. Lipids are small molecules that do not exceed about 800 Da.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-026","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":26,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Morphine and codeine are examples of which class of secondary metabolites?","image":"","options":["Essential oils","Pigments","Alkaloids","Polymeric substances"],"optionsInImage":false,"answer":["3"],"explanation":"Table 9.3 lists morphine and codeine as alkaloids. Do not confuse them with the 'drugs' category, which has vinblastin and curcumin as its examples.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-027","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":27,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"With reference to the graph of potential energy versus progress of reaction (concept of activation energy), how many of the following statements are correct?\n(i) The y-axis represents the potential energy content.\n(ii) If the product lies at a lower energy level than the substrate, the reaction is exothermic.\n(iii) An enzyme lowers the activation energy and also changes the energy difference between substrate and product.\n(iv) Intermediate structural states between the stable substrate and product are unstable.\n(v) The transition state lies at a higher energy level than the substrate.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (i), (ii), (iv) and (v) are correct, which makes four. Statement (iii) is wrong: an enzyme only lowers the energy barrier (the activation energy) and does not change the energy levels of the substrate or the product.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-028","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":28,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A student takes 50 g of fresh liver tissue and dries it completely, obtaining 10 g. The dried tissue is then fully burnt, leaving 1 g of residue. Which inference is correct?","image":"","options":["The 40 g lost on drying represents the acid-soluble pool of the tissue","The 1 g residue consists mainly of proteins and nucleic acids","The 10 g dry material is equivalent to the acid-insoluble fraction","About 80% of the tissue was water, and the 9 g lost on burning was mainly carbon compounds oxidised to $CO_2$ and water vapour"],"optionsInImage":false,"answer":["4"],"explanation":"Wet weight minus dry weight gives 40 g of water, which is 80% of the tissue, and burning removes carbon compounds as gases. The 1 g ash is inorganic. The trap is mixing up this destructive drying/burning experiment with the trichloroacetic acid fractionation.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-029","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":29,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are secondary metabolites?\nConcanavalin A, abrin, lecithin, curcumin, glycine, anthocyanin, rubber, cholesterol","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["3"],"explanation":"Concanavalin A (lectin), abrin (toxin), curcumin (drug), anthocyanin (pigment) and rubber (polymeric substance) are secondary metabolites, giving five in total. Lecithin, glycine and cholesterol are primary metabolites found in animal tissues.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-030","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":30,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Some nucleic acids can catalyse biochemical reactions in the same way as proteinaceous enzymes. What are these catalytic nucleic acids called?","image":"","options":["Ribozymes","Apoenzymes","Coenzymes","Isozymes"],"optionsInImage":false,"answer":["1"],"explanation":"Almost all enzymes are proteins, but certain nucleic acids with catalytic power are called ribozymes. An apoenzyme is only the protein part of an enzyme that needs a cofactor.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-031","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":31,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A glycogen molecule is drawn as a main chain from which 3 side branches arise. Following the convention that the right end of a chain is reducing and every other free end is non-reducing, how many reducing and non-reducing ends does this molecule have?","image":"","options":["1 reducing, 1 non-reducing","4 reducing, 1 non-reducing","1 reducing, 4 non-reducing","4 reducing, 4 non-reducing"],"optionsInImage":false,"answer":["3"],"explanation":"The molecule has only one reducing end, at the right end of the main chain. The non-reducing ends are the left end of the main chain plus the free end of each of the 3 branches, giving 4. The trap is assuming each branch also adds a reducing end.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-032","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":32,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II:\nList-I\n(a) Skeletal muscle under anaerobic conditions\n(b) Yeast during fermentation\n(c) Normal aerobic conditions\n(d) Number of enzyme-catalysed reactions converting glucose to pyruvic acid\nList-II\n(i) Pyruvic acid\n(ii) Ethanol\n(iii) Lactic acid\n(iv) Ten","image":"","options":["a-iii, b-ii, c-i, d-iv","a-ii, b-iii, c-i, d-iv","a-iii, b-i, c-ii, d-iv","a-i, b-ii, c-iii, d-iv"],"optionsInImage":false,"answer":["1"],"explanation":"The glucose-to-pyruvic acid pathway has ten enzyme-catalysed steps. Under normal aerobic conditions it ends in pyruvic acid. With one or two extra reactions, it gives lactic acid in anaerobic skeletal muscle and ethanol in fermenting yeast.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-033","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":33,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A triglyceride is formed when all three hydroxyl groups of glycerol are esterified with palmitic acid. What is the total number of carbon atoms in this triglyceride molecule?","image":"","options":["48","51","54","19"],"optionsInImage":false,"answer":["2"],"explanation":"Esterification removes water but no carbon atoms. The molecule therefore keeps 3 carbons from glycerol plus 3 × 16 = 48 carbons from the fatty acids, giving 51. Choosing 48 forgets the glycerol backbone.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-034","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":34,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Lipids appear in the acid-insoluble fraction even though their molecular weights do not exceed about 800 Da.\nReason (R): Grinding a tissue breaks the cell membrane and other membranes into fragments that form water-insoluble vesicles.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Lipids are arranged in membranes. When the tissue is ground, these membranes break into insoluble vesicles that separate with the acid-insoluble pool. That is why small lipid molecules end up in the macromolecular fraction.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-035","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":35,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about enzyme cofactors are correct?\n(i) The protein portion of an enzyme that needs a cofactor is called the apoenzyme.\n(ii) Prosthetic groups are inorganic ions loosely attached to the enzyme.\n(iii) A single coenzyme may serve as a cofactor in a number of different enzyme-catalysed reactions.\n(iv) Haem forms part of the active site of peroxidase and catalase.\n(v) Removing the cofactor from an enzyme leaves its catalytic activity unaffected.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (i), (iii) and (iv) are correct. Prosthetic groups are organic and tightly bound to the apoenzyme, so (ii) is wrong. Catalytic activity is lost when the cofactor is removed, so (v) is wrong.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-036","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":36,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Glycogen is a homopolymer made of","image":"","options":["Glucose units","Galactose units","Ribose units","Aminoacids"],"optionsInImage":false,"answer":["1"],"explanation":"Glycogen is the storage polysaccharide of animals. It is a branched homopolymer made only of glucose units.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q11)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-037","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":37,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Glycerol, a simple lipid found esterified with fatty acids in many lipids, is chemically described as:","image":"","options":["Trihydroxy propane","Dihydroxy ethane","Trihydroxy butane","Monohydroxy propane"],"optionsInImage":false,"answer":["1"],"explanation":"Glycerol is trihydroxy propane: a three-carbon chain carrying three –OH groups. These hydroxyl groups can each be esterified with a fatty acid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-038","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":38,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Aminoacids, have both an amino group and a carboxyl group in their structure. Which one of the following is an amino acid?","image":"","options":["Formic acid","Glycerol","Glycolic Acid","Glycine"],"optionsInImage":false,"answer":["4"],"explanation":"Glycine is the simplest amino acid; its R group is a hydrogen atom, and it carries both an amino and a carboxyl group. The other options lack an amino group.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q3)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-039","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":39,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the following statements about protein structure:\n(a) The first amino acid of a polypeptide is the N-terminal amino acid.\n(b) Only right-handed helices are observed in proteins.\n(c) Adult human haemoglobin consists of four identical subunits.\n(d) Quaternary structure describes how individual folded subunits are arranged with respect to each other.\n(e) The entire protein thread is folded into a helix.\nWhich of the following is the correct set of true statements?","image":"","options":["(a), (b) and (d) only","(a), (c) and (d) only","(b), (d) and (e) only","(a), (b), (c) and (d) only"],"optionsInImage":false,"answer":["1"],"explanation":"Haemoglobin has two α and two β subunits, so its four subunits are not all identical. Also, only some portions of a protein chain are helical. That leaves (a), (b) and (d) as the true statements.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-040","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":40,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Rate of a reaction is defined as $\\frac{\\delta P}{\\delta t}$. An uncatalysed reaction follows the general rule of thumb for the effect of temperature on rate. Its rate at 25°C is R. What would its rate be at 45°C?","image":"","options":["2R","4R","20R","R/4"],"optionsInImage":false,"answer":["2"],"explanation":"The rule of thumb says the rate doubles for every 10°C rise. A 20°C rise means two doublings, so the rate becomes $2 \\times 2 = 4$ times, i.e. 4R. A common trap is to double only once and choose 2R.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-041","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":41,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about proteins is INCORRECT?","image":"","options":["Antibodies are proteins that fight infectious agents","Some proteins transport nutrients across the cell membrane","Insulin is a polymer in which a single type of amino acid repeats n times","Proteins are linear chains of amino acids"],"optionsInImage":false,"answer":["3"],"explanation":"Insulin is a protein, so it is a heteropolymer made of different amino acids rather than one amino acid repeated. The other three statements agree with NCERT's description of proteins and their functions.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-042","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":42,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about adult human haemoglobin are correct?\n(a) It consists of four polypeptide subunits.\n(b) All four of its subunits are identical to one another.\n(c) Its subunits are of two types, $\\alpha$ and $\\beta$.\n(d) The arrangement of its subunits with respect to each other is its quaternary structure.\n(e) Because it has quaternary structure, its individual subunits lack tertiary folding.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (a), (c) and (d) are correct. Only pairs of subunits are identical, so (b) is wrong. Quaternary structure is the arrangement of already folded subunits, so (e) is wrong.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-043","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":43,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Complete hydrolysis of a single monomer isolated from a nucleic acid yields uracil, ribose and phosphate. The monomer and the nucleic acid it came from are most likely:","image":"","options":["Thymidylic acid; DNA","Uridine; RNA","Uridylic acid; RNA","Cytidylic acid; DNA"],"optionsInImage":false,"answer":["3"],"explanation":"Base, sugar and phosphate together make a nucleotide, so the monomer is uridylic acid; ribose identifies the nucleic acid as RNA. Uridine is wrong because a nucleoside lacks the phosphate.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-044","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":44,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Concanavalin A, listed among the secondary metabolites, belongs to which category?","image":"","options":["Toxins","Lectins","Alkaloids","Terpenoids"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT gives concanavalin A as the example of a lectin. Abrin and ricin are the toxins, morphine and codeine are the alkaloids, and monoterpenes and diterpenes are the terpenoids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-045","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":45,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which type of helix is observed in the secondary structure of proteins?","image":"","options":["Only left-handed helices","Both right-handed and left-handed helices in equal proportion","Only right-handed helices","Only triple helices"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT states that only right-handed helices are observed in proteins. Left-handed and triple helices are distractors.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-046","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":46,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Lipids are recovered in the acid-insoluble fraction even though their molecular weight does not exceed about 800 Da.\nReason (R): When a tissue is ground, cell membranes break into fragments that form water-insoluble vesicles, and these separate with the acid-insoluble pool.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Lipids are small molecules but are organised into membranes. On grinding, these membranes form insoluble vesicles that settle with the macromolecular fraction. This is exactly why lipids appear there, even though they are not strictly macromolecules.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-047","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":47,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are nucleosides?\nAdenosine, Uridylic acid, Cytidine, Thymidine, Guanylic acid, Uracil, Guanosine","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"The four nucleosides (base + sugar) are adenosine, cytidine, thymidine and guanosine. Uridylic acid and guanylic acid are nucleotides because they also carry a phosphate. Uracil is only a nitrogen base.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-048","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":48,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements are correct?\n(i) Cellulose is a homopolymer made of only glucose units.\n(ii) In a glycogen chain, the left end is the reducing end.\n(iii) Chitin has amino-sugars and chemically modified sugars as its building blocks.\n(iv) Cotton fibre and paper made from plant pulp are cellulosic.\n(v) Glycogen is the storage polysaccharide of plant tissues.\n(vi) Glycogen is a branched polysaccharide.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (i), (iii), (iv) and (vi) are correct. Statement (ii) is wrong because the right end of the chain is the reducing end and the left end is the non-reducing end. Statement (v) is wrong because starch is the plant storage form, while glycogen is the animal variant.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-049","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":49,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"According to NCERT, the active site of an enzyme is best described as:","image":"","options":["A crevice or pocket formed when the folded polypeptide chain criss-crosses itself, into which the substrate fits","The N-terminal amino acid of the polypeptide, where the substrate attaches","A linear stretch of the primary structure that stays unfolded so the substrate can reach it","A metal ion attached to the surface of the enzyme"],"optionsInImage":false,"answer":["1"],"explanation":"When the chain folds into its tertiary structure, it criss-crosses itself and forms pockets. One such pocket is the active site, where the substrate binds. The active site therefore depends on folding, not on a single terminal residue or an unfolded stretch.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-050","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":50,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (Protein) with List-II (Function).\nList-I:\nA. Collagen\nB. Trypsin\nC. Insulin\nD. Antibody\nList-II:\nI. Hormone\nII. Fights infectious agents\nIII. Intercellular ground substance\nIV. Enzyme\nChoose the correct option:","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"The correct pairs are collagen with intercellular ground substance, trypsin with enzyme, insulin with hormone and antibody with fighting infectious agents. Students often swap trypsin and insulin, but trypsin is an enzyme and insulin is a hormone.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-051","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":51,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (protein) with List-II (function):\nList-I\nA. Collagen\nB. Trypsin\nC. Insulin\nD. GLUT-4\nList-II\n(i) Enables glucose transport into cells\n(ii) Hormone\n(iii) Intercellular ground substance\n(iv) Enzyme","image":"","options":["A-(iv), B-(iii), C-(ii), D-(i)","A-(iii), B-(ii), C-(iv), D-(i)","A-(i), B-(iv), C-(ii), D-(iii)","A-(iii), B-(iv), C-(ii), D-(i)"],"optionsInImage":false,"answer":["4"],"explanation":"Collagen forms intercellular ground substance, trypsin is an enzyme, insulin is a hormone, and GLUT-4 enables glucose transport into cells. Do not confuse collagen, a structural protein, with trypsin, an enzyme.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-052","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":52,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Inulin is a polysaccharide built from repeating units of which monosaccharide?","image":"","options":["Glucose","Fructose","Ribose","Glucosamine"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT describes inulin as a polymer of fructose. Cellulose, starch and glycogen are the glucose-based polysaccharides, which makes glucose the common wrong choice.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-053","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":53,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A homopolymer has only one type of building block called monomer repeated ‘n’ number of times. A heteropolymer has more than one type of monomer. Proteins are heteropolymers usually made of","image":"","options":["20 types of monomers","40 types of monomers","30 types of monomers","only one type of monomer"],"optionsInImage":false,"answer":["1"],"explanation":"Proteins are polypeptide chains built from amino acids. Twenty types of amino acids usually serve as their monomers.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q9)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-054","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":54,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (enzyme class) with List-II (type of reaction catalysed):\nList-I\nA. Transferases\nB. Lyases\nC. Ligases\nD. Isomerases\nList-II\n(i) Inter-conversion of optical, geometric or positional isomers\n(ii) Linking together of two compounds, e.g., forming C–O, C–S or C–N bonds\n(iii) Removal of groups from substrates by non-hydrolytic mechanisms, leaving double bonds\n(iv) Transfer of a group other than hydrogen between a pair of substrates","image":"","options":["A-(iv), B-(iii), C-(ii), D-(i)","A-(iii), B-(iv), C-(i), D-(ii)","A-(iv), B-(ii), C-(iii), D-(i)","A-(ii), B-(iii), C-(iv), D-(i)"],"optionsInImage":false,"answer":["1"],"explanation":"Transferases move a group (not hydrogen) between substrates, and lyases remove groups without hydrolysis, leaving double bonds. Ligases join two compounds, and isomerases interconvert isomers. Lyases and ligases are easily confused because their names sound alike.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-055","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":55,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Palmitic acid is written as CH$_3$(CH$_2$)$_{14}$COOH. A fatty acid is described as a carboxyl group attached to an R group. How many carbon atoms are present in the R group of palmitic acid?","image":"","options":["14","15","16","17"],"optionsInImage":false,"answer":["2"],"explanation":"The R group is CH$_3$(CH$_2$)$_{14}$–, which has 1 + 14 = 15 carbons. The carboxyl carbon is the 16th carbon of the molecule and is not part of the R group.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-056","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":56,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A protein is imagined as a line, with the first amino acid at the left end. The amino acid at the right end of this line is called the:","image":"","options":["N-terminal amino acid","C-terminal amino acid","Active-site amino acid","Zwitterionic amino acid"],"optionsInImage":false,"answer":["2"],"explanation":"The right end carries the last amino acid, which is the C-terminal amino acid. The first amino acid, at the left end, is the N-terminal amino acid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-057","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":57,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A student grinds liver tissue in trichloroacetic acid and strains the slurry through cheesecloth. In the retentate, she detects a non-polymeric organic compound with a molecular weight of about 750 Da that is not soluble in water. This compound is most likely:","image":"","options":["A nucleotide that failed to dissolve because of its high molecular weight","A polysaccharide such as glycogen","A free amino acid such as serine","A phospholipid carried along in membrane vesicles"],"optionsInImage":false,"answer":["4"],"explanation":"A compound that is small (under 800 Da), non-polymeric and found in the acid-insoluble retentate fits a membrane lipid such as a phospholipid. It separates there because membrane fragments form insoluble vesicles. Nucleotides and amino acids remain in the acid-soluble filtrate, and glycogen is a large polymer.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-058","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":58,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Lipids appear in the acid-insoluble fraction, yet they are not strictly macromolecules.\nReason (R): When a tissue is ground, cell membranes break into fragments that form water-insoluble vesicles, and these separate along with the acid-insoluble pool.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Lipids are small molecules with molecular weights not exceeding about 800 Da, so they are not strictly macromolecules. They appear in the macromolecular fraction only because membrane fragments form insoluble vesicles that separate with that fraction. R therefore correctly explains why A is true.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-059","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":59,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (category of secondary metabolite) with List-II (example):\nList-I\nA. Alkaloids\nB. Toxins\nC. Lectins\nD. Drugs\nList-II\nI. Concanavalin A\nII. Vinblastin\nIII. Morphine\nIV. Ricin\nChoose the correct answer.","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"Morphine is an alkaloid and ricin is a toxin. Concanavalin A is a lectin, and vinblastin is a drug. A common trap is placing ricin and concanavalin A in each other's category.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-060","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":60,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are secondary metabolites?\nRubber, curcumin, glucose, abrin, lemon grass oil, adenylic acid, concanavalin A, palmitic acid","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["3"],"explanation":"Five are secondary metabolites: rubber, curcumin, abrin, lemon grass oil and concanavalin A. Glucose, adenylic acid and palmitic acid are primary metabolites (a sugar, a nucleotide and a fatty acid).","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-061","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":61,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Carbonic anhydrase speeds up the formation of carbonic acid from $CO_2$ and $H_2O$ by about 10 million times.\nReason (R): An enzyme works by reducing the energy difference between the substrate and the product of a reaction.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"The rate rises from about 200 molecules per hour to about 600,000 per second, an increase of roughly $10^7$ times, so A is true. Enzymes lower the activation energy, which is the gap between the substrate and the transition state. They do not change the energy difference between S and P, so R is false.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-062","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":62,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The coenzymes NAD and NADP contain which vitamin as an essential chemical component?","image":"","options":["Riboflavin","Niacin","Thiamine","Ascorbic acid"],"optionsInImage":false,"answer":["2"],"explanation":"Nicotinamide adenine dinucleotide (NAD) and NADP contain the vitamin niacin. This illustrates that vitamins are essential components of many coenzymes.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-063","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":63,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match the proteins in List-I with their functions in List-II.\nList-I\nA. Collagen\nB. Trypsin\nC. GLUT-4\nD. Receptor\nList-II\nI. Enzyme\nII. Enables glucose transport into cells\nIII. Intercellular ground substance\nIV. Sensory reception of smell, taste and hormones\nChoose the correct option.","image":"","options":["A-I, B-III, C-II, D-IV","A-III, B-I, C-IV, D-II","A-III, B-I, C-II, D-IV","A-II, B-I, C-III, D-IV"],"optionsInImage":false,"answer":["3"],"explanation":"Collagen forms intercellular ground substance and trypsin is an enzyme. GLUT-4 enables glucose to enter cells, and receptors handle sensory reception of smell, taste and hormones. A common trap is swapping GLUT-4 with receptors, since both are membrane proteins.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-064","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":64,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Adenine\nB. Adenosine\nC. Adenylic acid\nD. Thymine\nList-II\nI. Nucleotide\nII. Pyrimidine\nIII. Purine\nIV. Nucleoside\nChoose the correct option:","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"Adenine is a purine base and adenosine is its nucleoside (base + sugar). Adenylic acid is the nucleotide (base + sugar + phosphate), and thymine is a pyrimidine. The trap is confusing the names adenosine and adenylic acid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-065","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":65,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"When a dried tissue is fully burnt, the residue called 'ash' mainly contains:","image":"","options":["Carbon compounds such as sugars and amino acids","Proteins and nucleic acids","Water and dissolved gases","Inorganic elements such as calcium and magnesium"],"optionsInImage":false,"answer":["4"],"explanation":"On burning, all carbon compounds are oxidised to $CO_2$ and water vapour and escape. What remains as ash is inorganic material such as calcium and magnesium.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-066","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":66,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A slurry of tissue ground in trichloroacetic acid is strained through cheesecloth. What is the material that passes through the cloth technically called?","image":"","options":["Acid-insoluble fraction","Retentate","Acid-soluble pool","Ash"],"optionsInImage":false,"answer":["3"],"explanation":"The filtrate is technically called the acid-soluble pool, and thousands of organic compounds are found in it. The retentate left on the cloth is the acid-insoluble fraction.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-067","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":67,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Biologists often draw a protein as a line on paper. Which option correctly identifies the first amino acid of the chain and its position on that line?","image":"","options":["C-terminal amino acid, drawn at the left end","N-terminal amino acid, drawn at the right end","N-terminal amino acid, drawn at the left end","C-terminal amino acid, drawn at the right end"],"optionsInImage":false,"answer":["3"],"explanation":"In the line model, the first amino acid is the N-terminal amino acid and is placed at the left end. The last amino acid is the C-terminal amino acid and is placed at the right end.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-068","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":68,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about the inhibition of succinic dehydrogenase by malonate is correct?","image":"","options":["Malonate permanently denatures succinic dehydrogenase by breaking its tertiary structure","Malonate binds a site far from the active site because it is structurally unrelated to succinate","Malonate resembles succinate and competes with it for the substrate-binding site of the enzyme","Malonate acts as a coenzyme that speeds up the oxidation of succinate"],"optionsInImage":false,"answer":["3"],"explanation":"Malonate is a competitive inhibitor. It closely resembles the substrate succinate in structure, so it occupies the substrate-binding site and stops succinate from binding. Inhibitors of this kind are used in controlling bacterial pathogens.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-069","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":69,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Thymidine is a nucleoside.\nStatement II: In a nucleotide, the phosphate group is esterified directly to the nitrogenous base.\nChoose the correct option.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Thymidine (thymine plus sugar) is indeed a nucleoside. In a nucleotide, however, the phosphate is esterified to the sugar, not to the base.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-070","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":70,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"When a living tissue is ground in trichloroacetic acid and filtered, the compounds in the acid-soluble pool have molecular weights in which approximate range?","image":"","options":["1000 to 10,000 Da","18 to about 800 Da","10,000 Da and above","800 to 1000 Da only"],"optionsInImage":false,"answer":["2"],"explanation":"All compounds in the acid-soluble pool range from about 18 Da (water) to around 800 Da. The value of 10,000 Da and above applies to the polymeric macromolecules in the acid-insoluble fraction.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-071","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":71,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about lipids are correct?\n(i) Lipids are generally insoluble in water.\n(ii) Glycerol is itself regarded as a simple lipid.\n(iii) Phospholipids contain phosphorus and a phosphorylated organic compound.\n(iv) Neural tissues contain lipids with more complex structures.\n(v) Fats have a lower melting point than oils.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (i) to (iv) are correct. Statement (v) is reversed: oils have the lower melting point, which is why they stay liquid in winter.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-072","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":72,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II:\nList-I\nA. Skeletal muscle under anaerobic conditions\nB. Yeast during fermentation\nC. Normal aerobic conditions\nD. Glucose to pyruvic acid\nList-II\nI. Ethanol\nII. Pyruvic acid as end product\nIII. Lactic acid\nIV. Ten enzyme-catalysed reactions\nChoose the correct answer:","image":"","options":["A-III, B-I, C-II, D-IV","A-I, B-III, C-II, D-IV","A-III, B-I, C-IV, D-II","A-II, B-I, C-III, D-IV"],"optionsInImage":false,"answer":["1"],"explanation":"The same glucose-to-pyruvate pathway has ten enzymatic steps. With one or two extra reactions, it gives lactic acid in anaerobic muscle and ethanol in yeast fermentation. Under aerobic conditions, pyruvic acid is formed.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-073","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":73,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following is an example of a phospholipid found in the cell membrane?","image":"","options":["Cholesterol","Palmitic acid","Lecithin","Triglyceride"],"optionsInImage":false,"answer":["3"],"explanation":"Lecithin is the textbook example of a phospholipid, a lipid that contains phosphorus and a phosphorylated organic compound. The other options are lipids, but none of them is a phospholipid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-074","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":74,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Starch gives a blue colour with iodine, but cellulose does not.\nReason (R): Cellulose is a heteropolymer made of several different monosaccharides.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"Starch forms helical secondary structures that hold $I_2$ and give the blue colour, while cellulose lacks complex helices, so A is true. R is false because cellulose is a homopolymer of glucose only.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-075","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":75,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements is INCORRECT?","image":"","options":["Arachidonic acid has an R group containing 19 carbon atoms, the upper limit of R-group size mentioned for fatty acids","A diglyceride has two fatty acids esterified with glycerol","Lipids appear in the acid-insoluble fraction because, like proteins, they are polymers with molecular weights of ten thousand daltons and above","Lipids of the cell membrane form water-insoluble vesicles when a tissue is ground"],"optionsInImage":false,"answer":["3"],"explanation":"Lipids are small molecules that do not exceed about 800 Da, so they are not strictly macromolecules. They separate with the acid-insoluble pellet only because membrane fragments form water-insoluble vesicles during grinding.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-076","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":76,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which one of the following is a primary metabolite?","image":"","options":["Morphine","Anthocyanin","Ricin","Glycine"],"optionsInImage":false,"answer":["4"],"explanation":"Amino acids such as glycine are present in animal tissues and have known physiological roles, so they are primary metabolites. Morphine, anthocyanin and ricin are secondary metabolites.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-077","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":77,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A potential energy versus progress-of-reaction graph for a reaction S → P shows the product at a lower energy level than the substrate. Two curves are drawn: a tall peak for the uncatalysed reaction and a shorter peak for the enzyme-catalysed reaction. Consider the statements:\nI. The reaction is exothermic.\nII. The enzyme reduces the energy difference between S and P.\nIII. The transition state has higher potential energy than both S and P.\nIV. Activation energy is the difference in energy between the transition state and P.\nWhich of the statements are correct?","image":"","options":["I and III only","I, II and III only","II and IV only","I, III and IV only"],"optionsInImage":false,"answer":["1"],"explanation":"P lies below S, so the reaction is exothermic, and the transition state is the highest-energy point on the curve. Enzymes lower only the activation barrier, not the S–P energy difference. Activation energy is measured from S to the transition state, not from P.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-078","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":78,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Based on the comparison of elemental composition of the earth's crust and the human body (% weight), which of the following elements is relatively MORE abundant in the human body than in the earth's crust?","image":"","options":["Silicon","Carbon","Sodium","Magnesium"],"optionsInImage":false,"answer":["2"],"explanation":"Carbon makes up about 18.5% of the human body but only about 0.03% of the earth's crust. Silicon, sodium and magnesium are all more abundant in the crust than in the body.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-079","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":79,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which class of biomolecules makes up about 10-15% of the total cellular mass?","image":"","options":["Proteins","Lipids","Ions","Nucleic acids"],"optionsInImage":false,"answer":["1"],"explanation":"Proteins make up 10-15% of cellular mass. Nucleic acids make up 5-7%, lipids about 2% and ions about 1%.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-080","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":80,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): The structure of an amino acid in solution changes with the pH of the solution.\nReason (R): The $-NH_2$ and $-COOH$ groups of amino acids are ionizable.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Both groups can gain or lose protons, so the ionic form of the amino acid shifts as pH changes. The ionizable nature of these groups is exactly why the structure becomes pH-dependent.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-081","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":81,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Even in an exothermic reaction, the substrate must pass through a higher energy transition state before forming the product.\nReason (R): Activation energy is the difference in energy content between the substrate and the product.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"Every reaction, whether exothermic or endothermic, goes through a high-energy transition state, so A is true. Activation energy is the gap between the substrate and the transition state, not between the substrate and the product, so R is false.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-082","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":82,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Nucleic acids separate into the acid-insoluble fraction when a living tissue is ground in trichloroacetic acid.\nReason (R): Nucleic acids are polynucleotides with molecular weights in the range of ten thousand daltons and above.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Nucleic acids are true polymers (polynucleotides) with very high molecular weights. This is why they belong to the acid-insoluble, macromolecular fraction, so R correctly explains A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-083","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":83,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Glycerol, a simple lipid that often occurs esterified with fatty acids, is chemically described as:","image":"","options":["Trihydroxy propane","Dihydroxy propane","Trihydroxy butane","Trihydroxy ethane"],"optionsInImage":false,"answer":["1"],"explanation":"Glycerol is trihydroxy propane: a three-carbon chain with one –OH group on each carbon. Its three hydroxyl groups can be esterified with fatty acids to form mono-, di- or triglycerides.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-084","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":84,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following is a physical process and NOT a chemical reaction?","image":"","options":["Hydrolysis of starch into glucose","Reaction of $Ba(OH)_2$ with $H_2SO_4$ to form $BaSO_4$ and water","Conversion of water into vapour","Conversion of glucose into pyruvic acid"],"optionsInImage":false,"answer":["3"],"explanation":"A change of state, such as water becoming vapour, involves no breaking or forming of chemical bonds, so it is a physical process. The other three options all involve breaking old bonds and forming new ones.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-085","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":85,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In the usual way a polysaccharide chain such as glycogen is drawn, the reducing end lies at the:","image":"","options":["Left end of the chain","Right end of the chain","Tip of every branch","Centre of the main chain"],"optionsInImage":false,"answer":["2"],"explanation":"By NCERT convention, the right end of a polysaccharide chain is the reducing end and the left end is the non-reducing end. Branch tips are non-reducing ends, not reducing ends.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-086","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":86,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which one of the following statements about enzyme co-factors is incorrect?","image":"","options":["Haem is the prosthetic group of catalase and peroxidase and is part of their active site","The coenzymes NAD and NADP contain the vitamin niacin","Prosthetic groups associate with the apoenzyme only transiently during catalysis","Zinc acts as a metal-ion co-factor for carboxypeptidase"],"optionsInImage":false,"answer":["3"],"explanation":"Prosthetic groups are tightly bound to the apoenzyme. It is coenzymes whose association is transient and occurs during catalysis, so this statement swaps the two.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-087","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":87,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"GLUT-4 is a protein whose main function is to:","image":"","options":["Act as a hormone that lowers blood glucose","Enable the transport of glucose into cells","Digest proteins in the intestine","Fight infectious agents"],"optionsInImage":false,"answer":["2"],"explanation":"According to NCERT Table 9.5, GLUT-4 enables glucose transport into cells, so it is a transport protein. Insulin is the hormone, trypsin is the digestive enzyme, and antibodies fight infectious agents.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-088","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":88,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Starch gives a blue colour with iodine, but cellulose does not.\nStatement II: Cellulose is a heteropolymer made of different types of monosaccharides.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Starch forms helices that hold $I_2$, giving the blue colour, while cellulose lacks complex helices and cannot hold iodine. Statement II is wrong because cellulose is a homopolymer of glucose only.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-089","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":89,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"It is said that elemental composition of living organisms and that of inanimate objects (like earth’s crust) are similar in the sense that all the major elements are present in both. Then what would be the difference between these two groups? Choose a correct answer from among the following:","image":"","options":["Living organisms have more gold in them than inanimate objects.","Living organisms have more water in their body than inanimate objects.","Living organisms have more carbon, oxygen and hydrogen per unit mass than inanimate objects.","Living organisms have more calcium in them than inanimate objects."],"optionsInImage":false,"answer":["3"],"explanation":"Both living organisms and the earth's crust contain the major elements. Living matter, however, is much richer in carbon, hydrogen and oxygen per unit mass, because it is built from organic compounds.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q1)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-090","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":90,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the potential energy graph used to explain activation energy. How many of the following statements are correct?\n(i) The y-axis shows potential energy and the x-axis shows the progress of the reaction.\n(ii) If the product lies at a lower energy level than the substrate, the reaction is exothermic.\n(iii) An enzyme works by lowering the energy level of the product, which makes the reaction exothermic.\n(iv) Activation energy is the difference between the average energy content of the substrate and that of the transition state.\n(v) Endothermic reactions do not need to pass through a transition state.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (i), (ii) and (iv) are correct, so the answer is 3. An enzyme lowers the activation energy barrier, not the energy of the product, so (iii) is wrong. Both exothermic and endothermic reactions must pass through the higher-energy transition state, so (v) is wrong.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-091","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":91,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In NCERT's comparison of elements in the earth's crust and the human body, which element is the second most abundant in the earth's crust (27.7% by weight) but present only in negligible amounts in the human body?","image":"","options":["Calcium","Silicon","Sodium","Magnesium"],"optionsInImage":false,"answer":["2"],"explanation":"Silicon makes up about 27.7% of the earth's crust but is negligible in the human body. Calcium, sodium and magnesium are each present in measurable amounts in both.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-092","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":92,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (category of secondary metabolite) with List-II (example):\nList-I\nA. Pigments\nB. Terpenoids\nC. Essential oils\nD. Drugs\nList-II\nI. Lemon grass oil\nII. Vinblastin\nIII. Anthocyanins\nIV. Diterpenes","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-II, D-I","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"The correct pairs are: anthocyanins are pigments, diterpenes are terpenoids, lemon grass oil is an essential oil, and vinblastin is a drug.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-093","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":93,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A fatty acid whose hydrocarbon chain contains one or more C=C double bonds is termed:","image":"","options":["Saturated fatty acid","Unsaturated fatty acid","Phosphorylated fatty acid","Esterified fatty acid"],"optionsInImage":false,"answer":["2"],"explanation":"Fatty acids with one or more C=C double bonds are unsaturated. Saturated fatty acids have no double bonds.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-094","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":94,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Essential amino acids are best defined as amino acids that:","image":"","options":["Occur in every protein of the body","Cannot be made by our body and must be obtained through the diet","Are synthesised by the body in large quantities","Are found only in plant proteins"],"optionsInImage":false,"answer":["2"],"explanation":"Essential amino acids must be supplied through food, which is why dietary proteins serve as their source. Non-essential amino acids are the ones our body can make.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-095","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":95,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A piece of liver is ground with trichloroacetic acid ($Cl_3CCOOH$) in a mortar and pestle. The thick slurry is then strained through cheesecloth. What is the filtrate that passes through the cloth called?","image":"","options":["Acid-insoluble fraction","Acid-soluble pool","Ash","Retentate"],"optionsInImage":false,"answer":["2"],"explanation":"The filtrate that passes through the cloth is the acid-soluble pool. The material held back is the retentate, also called the acid-insoluble fraction. Ash is obtained only by burning the tissue, not by straining.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-096","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":96,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which metal ion acts as a cofactor for the proteolytic enzyme carboxypeptidase?","image":"","options":["Magnesium","Iron","Zinc","Copper"],"optionsInImage":false,"answer":["3"],"explanation":"Zinc is the metal-ion cofactor of carboxypeptidase. It forms coordination bonds with side chains at the active site and also with the substrate. Iron is part of haem, which is a prosthetic group, not a free metal-ion cofactor in this example.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-097","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":97,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): When iodine solution is added, a starch suspension turns blue but a cellulose suspension does not.\nReason (R): Starch forms helical secondary structures that can hold $I_2$ molecules, whereas cellulose lacks complex helices.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"The blue colour comes from the starch–$I_2$ complex, which forms because iodine sits inside the helical portions of starch. Cellulose lacks such complex helices, so it cannot hold $I_2$ and gives no blue colour. R therefore directly explains A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-098","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":98,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are true biomacromolecules (polymers with molecular weight of about 10,000 Da or more)?\nCellulose, lecithin, DNA, triglyceride, haemoglobin, palmitic acid, starch","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["2"],"explanation":"Cellulose, DNA, haemoglobin and starch are polymers, giving four true macromolecules. Lecithin, triglyceride and palmitic acid are lipids, which are small molecules and not strictly macromolecules.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-099","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":99,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following reaction descriptions is correctly paired with its enzyme class?","image":"","options":["Transfer of hydrogen between substrates S and S' — Transferases","Removal of a group from a substrate by hydrolysis, leaving a double bond — Lyases","Joining of two compounds through formation of a C–N bond — Ligases","Inter-conversion of positional isomers — Ligases"],"optionsInImage":false,"answer":["3"],"explanation":"Ligases catalyse the linking of two compounds by forming bonds such as C–O, C–S, C–N or P–O. Transfer of hydrogen is an oxidoreduction, so it does not belong to transferases. Lyases act by non-hydrolytic mechanisms, and isomer interconversion is done by isomerases.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-100","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":100,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following polysaccharides is a polymer of fructose?","image":"","options":["Glycogen","Inulin","Cellulose","Starch"],"optionsInImage":false,"answer":["2"],"explanation":"Inulin is built from fructose units. Cellulose, starch and glycogen are all made of glucose, so fructose is the key to the answer.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-101","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":101,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the following substances: $K^+$, $Mg^{++}$, glycine, $NaCl$, $H_2O$, $SO_4^{2-}$, ribose, $CaCO_3$.\nHow many of these are inorganic constituents of living tissues, of the kind listed in NCERT's table of representative inorganic constituents?","image":"","options":["4","5","6","7"],"optionsInImage":false,"answer":["3"],"explanation":"$K^+$, $Mg^{++}$, $NaCl$, $H_2O$, $SO_4^{2-}$ and $CaCO_3$ are inorganic, giving six. Glycine (an amino acid) and ribose (a sugar) are organic biomolecules. Water is easy to overlook, but it counts as an inorganic constituent.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-102","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":102,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about metabolites is incorrect?","image":"","options":["Plant, fungal and microbial cells contain thousands of compounds other than primary metabolites","Some secondary metabolites have ecological importance","Primary metabolites have identifiable functions in normal physiological processes","The roles of all secondary metabolites in their host organisms are well understood"],"optionsInImage":false,"answer":["4"],"explanation":"NCERT states that we do not, at the moment, understand the roles of all secondary metabolites in their host organisms. The other three statements agree with the text.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-103","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":103,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements are correct?\n(i) Palmitic acid has 16 carbon atoms, including the carboxyl carbon.\n(ii) Arachidonic acid has 20 carbon atoms, including the carboxyl carbon.\n(iii) Glycerol is trihydroxy propane.\n(iv) Lysine is an acidic amino acid.\n(v) Tryptophan is an aromatic amino acid.\n(vi) The R group of serine is a methyl group.","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (i), (ii), (iii) and (v) are correct, giving 4. Lysine is a basic amino acid (glutamic acid is the acidic example). Serine has a hydroxy methyl R group, while a methyl R group belongs to alanine.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-104","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":104,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Three polysaccharide samples were tested:\nP: gives only glucose on complete hydrolysis, gives no blue colour with iodine, and is the main material of plant cell walls.\nQ: gives only fructose on complete hydrolysis.\nR: gives only glucose on complete hydrolysis, gives a blue colour with iodine, and is extracted from potato tubers as stored food.\nIdentify P, Q and R.","image":"","options":["P - Starch, Q - Inulin, R - Cellulose","P - Cellulose, Q - Inulin, R - Starch","P - Cellulose, Q - Glycogen, R - Starch","P - Glycogen, Q - Chitin, R - Starch"],"optionsInImage":false,"answer":["2"],"explanation":"P is cellulose: a glucose homopolymer of cell walls with no helices to hold iodine. Q is inulin, the fructose polymer. R is starch, the helical glucose polymer that stores energy in plants and turns blue with $I_2$.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-105","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":105,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The following events occur during the catalytic cycle of an enzyme:\nP. The active site breaks chemical bonds of the substrate and an enzyme-product complex is formed.\nQ. The substrate binds to the active site of the enzyme.\nR. The products are released and the free enzyme can bind another substrate molecule.\nS. The enzyme changes its shape and fits more tightly around the substrate.\nSelect the correct sequence.","image":"","options":["Q → P → S → R","S → Q → P → R","Q → S → P → R","Q → S → R → P"],"optionsInImage":false,"answer":["3"],"explanation":"First the substrate binds (Q). Binding then induces the enzyme to change shape and fit more tightly (S). Next, bonds are broken and the EP complex forms (P), and finally the products are released (R), matching E + S → ES → EP → E + P. The common trap is placing the shape change before binding, but it is the binding that causes it.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-106","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":106,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Without any enzyme, about 200 molecules of $H_2CO_3$ form from $CO_2$ and $H_2O$ in one hour. With carbonic anhydrase, about 600,000 molecules form every second. By roughly what factor has the enzyme speeded up the reaction?","image":"","options":["About 3,000 times","About 10 thousand times","About 10 million times","About 10 billion times"],"optionsInImage":false,"answer":["3"],"explanation":"Per hour, the enzyme gives 600,000 × 3600 ≈ $2.16 \\times 10^9$ molecules, against 200 without it. This is a ratio of about $10^7$, i.e., about 10 million times. The 3,000 option comes from forgetting to convert seconds to hours.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-107","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":107,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Curcumin and vinblastin are listed as drugs among secondary metabolites.\nStatement II: Monoterpenes and diterpenes are examples of alkaloids.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Curcumin and vinblastin are indeed listed under drugs. Monoterpenes and diterpenes, however, are terpenoids; the alkaloid examples are morphine and codeine.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-108","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":108,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In an enzyme-catalysed reaction, the substrate concentration has been raised until the velocity reaches $V_{max}$. Temperature and pH are kept at their optimum values. Which of the following changes would increase the reaction velocity further?","image":"","options":["Doubling the substrate concentration","Adding more molecules of the same enzyme","Adding a competitive inhibitor that resembles the substrate","Raising the temperature well above the optimum"],"optionsInImage":false,"answer":["2"],"explanation":"At $V_{max}$, every enzyme molecule is already saturated with substrate, so the number of enzyme molecules is what limits the rate; adding more enzyme provides extra active sites and raises the velocity. The other options fail:\n- Extra substrate cannot raise $V_{max}$, since no free enzyme is left to bind it.\n- A competitive inhibitor blocks active sites.\n- Heating above the optimum denatures the enzyme.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-109","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":109,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Sugars are technically called carbohydrates, referring to the fact that their formulae are only multiple of C(H$_2$O). Hexoses therefore have six carbons, twelve hydrogens and six oxygen atoms. Glucose is a hexose. Choose from among the following another hexose.","image":"","options":["Fructose","Erythrose","Ribulose","Ribose"],"optionsInImage":false,"answer":["1"],"explanation":"Fructose has the formula C$_6$H$_{12}$O$_6$, so it is a hexose like glucose. Erythrose is a tetrose, while ribose and ribulose are pentoses.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q5)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-110","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":110,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which protein is the most abundant protein in the whole of the biosphere?","image":"","options":["Collagen","Haemoglobin","RuBisCO","Insulin"],"optionsInImage":false,"answer":["3"],"explanation":"Ribulose bisphosphate carboxylase-oxygenase (RuBisCO) is the most abundant protein in the entire biosphere. Collagen is a common trap because it is the most abundant protein only in the animal world.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-111","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":111,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about protein structure are correct?\n(i) Both right-handed and left-handed helices are commonly observed in proteins.\n(ii) The entire polypeptide chain of a protein exists as a continuous helix.\n(iii) Adult human haemoglobin has four subunits: two of the α type and two of the β type.\n(iv) Quaternary structure is possible only in proteins made of more than one polypeptide or subunit.\n(v) Tertiary structure gives a three-dimensional view of a protein and is absolutely necessary for many of its biological activities.","image":"","options":["1","2","3","4"],"optionsInImage":false,"answer":["3"],"explanation":"Statements (iii), (iv) and (v) are correct. Statement (i) is wrong because only right-handed helices are observed in proteins. Statement (ii) is wrong because only some portions of the protein thread form a helix; other regions fold into different forms.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-112","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":112,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (enzyme class) with List-II (type of reaction catalysed):\nList-I\nA. Transferases\nB. Hydrolases\nC. Lyases\nD. Ligases\nList-II\nI. Hydrolysis of peptide or glycosidic bonds\nII. Transfer of a group other than hydrogen between two substrates\nIII. Joining of two compounds by forming C–O, C–S or C–N bonds\nIV. Removal of groups by a mechanism other than hydrolysis, leaving double bonds\nChoose the correct answer.","image":"","options":["A-II, B-I, C-III, D-IV","A-II, B-I, C-IV, D-III","A-IV, B-I, C-II, D-III","A-III, B-IV, C-I, D-II"],"optionsInImage":false,"answer":["2"],"explanation":"Transferases move a group other than hydrogen, and hydrolases break bonds by hydrolysis. Lyases remove groups without hydrolysis and leave double bonds, while ligases join two compounds. Students often swap lyases and ligases.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-113","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":113,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A tissue homogenised in trichloroacetic acid was filtered, and the acid-insoluble fraction (retentate) was analysed. How many of the following would be expected in the retentate?\nGlucose, Proteins, Amino acids, Nucleic acids, Polysaccharides, Nucleotides, Lipids, Inorganic phosphate","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["2"],"explanation":"The acid-insoluble fraction holds only four kinds of organic compounds: proteins, nucleic acids, polysaccharides and lipids. Glucose, amino acids, nucleotides and inorganic ions such as phosphate are small molecules, so they stay in the acid-soluble pool. The trap is forgetting lipids, which separate with the insoluble fraction as membrane vesicles.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-114","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":114,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Inorganic compounds like sulphate and phosphate are detected in the acid-soluble fraction of a living tissue.\nReason (R): The acid-soluble fraction contains only organic compounds.\nChoose the correct option.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"NCERT states that sulphate, phosphate and similar inorganic compounds are seen in the acid-soluble fraction, so A is true. R is false because the pool contains inorganic constituents as well as organic ones.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-115","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":115,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following nitrogenous bases is a substituted purine?","image":"","options":["Cytosine","Thymine","Guanine","Uracil"],"optionsInImage":false,"answer":["3"],"explanation":"Adenine and guanine are substituted purines. Cytosine, thymine and uracil are substituted pyrimidines.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-116","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":116,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are made mainly of cellulose?\nCotton fibre; paper made from plant pulp; plant cell wall; exoskeleton of a cockroach; glycogen granules in liver cells","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Three items are cellulosic: cotton fibre, paper from plant pulp and the plant cell wall. A cockroach exoskeleton is made of chitin, and liver granules are glycogen.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-117","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":117,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II:\nList-I\n(a) Malonate\n(b) Haem\n(c) Zinc\n(d) Niacin\nList-II\n(i) Prosthetic group of catalase\n(ii) Cofactor of carboxypeptidase\n(iii) Vitamin component of NAD\n(iv) Competitive inhibitor of succinic dehydrogenase","image":"","options":["(a)-(iv), (b)-(i), (c)-(ii), (d)-(iii)","(a)-(i), (b)-(iv), (c)-(ii), (d)-(iii)","(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)","(a)-(ii), (b)-(i), (c)-(iv), (d)-(iii)"],"optionsInImage":false,"answer":["1"],"explanation":"Malonate resembles succinate, so it competitively inhibits succinic dehydrogenase. Haem is the tightly bound prosthetic group of catalase. Zinc is the metal-ion cofactor of carboxypeptidase. Niacin is the vitamin present in the coenzyme NAD.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-118","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":118,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"When we homogenise any tissue in an acid the acid soluble pool represents","image":"","options":["Cytoplasm","Cell membrane","Nucleus","Mitochondria"],"optionsInImage":false,"answer":["1"],"explanation":"The acid-soluble pool holds small molecules such as amino acids, sugars and nucleotides. According to NCERT, it roughly represents the composition of the cytoplasm.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q7)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-119","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":119,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A person follows a diet that completely lacks protein for a long period. Based on the role of dietary proteins, which amino acids are most likely to become deficient in the body?","image":"","options":["Essential amino acids, because the body cannot make them and must obtain them from food","Non-essential amino acids, because they can be obtained only from dietary proteins","All 20 amino acids equally, because the body cannot make any amino acid","None, because the body can synthesise all amino acids it needs"],"optionsInImage":false,"answer":["1"],"explanation":"Dietary proteins are the source of essential amino acids, which the body cannot make, so these would run short. Non-essential amino acids can still be made by the body, which is the trap in the second option.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-120","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":120,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I:\n(A) Adenine\n(B) Adenosine\n(C) Adenylic acid\n(D) Ribose\nList-II:\n(I) Nucleotide\n(II) Pentose monosaccharide\n(III) Purine base\n(IV) Nucleoside\nChoose the correct option.","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-I, C-IV, D-II","A-II, B-IV, C-I, D-III"],"optionsInImage":false,"answer":["1"],"explanation":"Adenine is a purine base. Adenosine is adenine plus sugar, a nucleoside, and adenylic acid has a phosphate as well, making it a nucleotide. Ribose is a pentose sugar; the usual trap is confusing adenosine with adenylic acid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-121","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":121,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: When a tissue is ground in trichloroacetic acid and strained, the polysaccharides are recovered in the acid-insoluble fraction.\nStatement II: Inulin is a polymer of glucose, just like cellulose.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Polysaccharides are macromolecules and separate into the acid-insoluble pellet, so Statement I is correct. Statement II is wrong because inulin is a polymer of fructose, not glucose.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-122","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":122,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In biology, the primary structure of a protein refers to:","image":"","options":["The folding of the polypeptide into a helix","The sequence of amino acids, that is, which amino acid is first, which is second, and so on","The arrangement of subunits with respect to each other","The three-dimensional folding of the chain like a ball"],"optionsInImage":false,"answer":["2"],"explanation":"Primary structure is the positional information of amino acids in the chain. Helix formation is secondary structure, ball-like folding is tertiary structure and subunit arrangement is quaternary structure.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-123","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":123,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about protein structure is incorrect?","image":"","options":["Alpha helix and beta-pleated sheet are forms of secondary structure","The entire length of every protein thread is coiled into a right-handed helix","Quaternary structure is seen only in proteins made of more than one polypeptide or subunit","Tertiary structure gives a three-dimensional view of a protein"],"optionsInImage":false,"answer":["2"],"explanation":"Only some portions of the protein thread form a helix. Other regions fold into other forms, such as beta-pleated sheets, so the claim about the entire thread is false.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-124","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":124,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following biomolecules are homopolymers?\nCellulose, Insulin, Collagen, Inulin, Trypsin, Antibody","image":"","options":["One","Two","Four","Six"],"optionsInImage":false,"answer":["2"],"explanation":"Only cellulose (made of glucose) and inulin (made of fructose) are made of a single type of monomer. Insulin, collagen, trypsin and antibodies are proteins, so they are heteropolymers of different amino acids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-125","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":125,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Secondary metabolites such as rubber, spices and scents are useful to human welfare.\nReason (R): The functions of all secondary metabolites in their host organisms are clearly known.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"Many secondary metabolites, such as rubber, drugs, spices, scents and pigments, are valuable to humans, so A is true. R is false because the roles of many secondary metabolites in their hosts are still not understood.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-126","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":126,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Gingelly oil remains in liquid form even during winter.\nReason (R): Oils have a lower melting point than fats.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Fats and oils are distinguished by melting point. Oils such as gingelly oil melt at a lower temperature, so they stay liquid in cold weather. R therefore directly explains A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-127","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":127,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The sugar present in the polynucleotide chain of DNA is:","image":"","options":["Ribose","Glucose","2'-deoxyribose","Fructose"],"optionsInImage":false,"answer":["3"],"explanation":"A nucleic acid containing 2'-deoxyribose is deoxyribonucleic acid (DNA). A nucleic acid containing ribose is RNA.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-128","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":128,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A homopolymer is best described as a polymer in which:","image":"","options":["Only one type of monomer repeats n number of times","Twenty different types of monomers are joined together","Monomers are joined only by hydrogen bonds","Two polypeptide chains are joined together"],"optionsInImage":false,"answer":["1"],"explanation":"A homopolymer has only one type of monomer repeating n times. Proteins are not homopolymers because they are built from many different types of amino acids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-129","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":129,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about enzymes and inorganic catalysts is INCORRECT?","image":"","options":["Inorganic catalysts work efficiently at high temperatures and high pressures.","Enzymes of most organisms get damaged at high temperatures, say above 40°C.","Enzymes isolated from organisms of hot vents and sulphur springs remain stable up to about 80°-90°C.","Enzymes from thermophilic organisms lose their catalytic power at temperatures just above 40°C."],"optionsInImage":false,"answer":["4"],"explanation":"Enzymes from thermophiles are thermally stable and keep their catalytic power even at 80°-90°C. Damage above about 40°C applies to ordinary enzymes, not to enzymes from thermophiles.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-130","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":130,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the following about the reaction $CO_2 + H_2O \\rightleftharpoons H_2CO_3$:\nStatement I: In the absence of any enzyme, only about 200 molecules of $H_2CO_3$ are formed in an hour.\nStatement II: Carbonic anhydrase, present in the cytoplasm, raises the rate to about 600,000 molecules per second, which is roughly a 10 million-fold acceleration.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["1"],"explanation":"Both figures agree with NCERT. As a check, 600,000 per second is about $2.2 \\times 10^9$ per hour, and dividing by 200 per hour gives roughly $10^7$, which is about a 10 million-fold increase.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-131","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":131,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A potential energy versus progress-of-reaction graph shows substrate S at a higher energy level than product P. Two humps lie between them: a tall one labelled 'without enzyme' and a shorter one labelled 'with enzyme'. Which interpretation of this graph is correct?","image":"","options":["Since P lies below S, the reaction needs no activation energy at all","The enzyme lowers the energy barrier to the transition state but does not change the energy difference between S and P","The enzyme makes the reaction exothermic by lowering the energy level of P","The transition state at the top of the hump is the most stable structure along the reaction pathway"],"optionsInImage":false,"answer":["2"],"explanation":"Enzymes reduce the activation energy, which is the gap between S and the transition state. The S–P energy difference stays the same, so the reaction is exothermic either way. Even exothermic reactions must pass through the high-energy, unstable transition state.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-132","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":132,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Thymidine and uridine both contain pyrimidine bases.\nStatement II: In a nucleoside, a phosphate group is esterified to the sugar.\nChoose the correct option:","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Thymine and uracil are pyrimidines, so their nucleosides thymidine and uridine contain pyrimidine bases. A phosphate esterified to the sugar defines a nucleotide, not a nucleoside.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-133","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":133,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (discipline) with List-II (how 'structure' of a molecule is usually described).\nList-I:\nA. Inorganic chemistry\nB. Organic chemistry\nC. Physics\nD. Biology (proteins)\nList-II:\nI. Three-dimensional view of molecules\nII. Description at four levels\nIII. Molecular formula\nIV. Two-dimensional view of molecules","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-II, D-I","A-III, B-I, C-IV, D-II","A-I, B-IV, C-III, D-II"],"optionsInImage":false,"answer":["1"],"explanation":"Inorganic chemists use molecular formulae such as NaCl, and organic chemists draw 2D views such as benzene. Physicists imagine 3D views, and biologists describe protein structure at four levels.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-134","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":134,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Malonate decreases the activity of succinic dehydrogenase.\nReason (R): Malonate closely resembles succinate in structure and competes with it for the substrate-binding site of the enzyme.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Malonate is a competitive inhibitor of succinic dehydrogenase. Because it resembles the substrate succinate, it occupies the substrate-binding site, so succinate cannot bind and enzyme activity falls. R therefore directly explains A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-135","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":135,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are nucleosides?\nAdenosine, Adenylic acid, Uridine, Guanine, Cytidine, Thymidylic acid, Thymidine","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"A nucleoside is a nitrogen base attached to a sugar, so adenosine, uridine, cytidine and thymidine are nucleosides (4 in total). Adenylic and thymidylic acids carry a phosphate, which makes them nucleotides, and guanine is only a free base.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-136","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":136,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Amino acids are grouped as acidic, basic or neutral based on the number of amino and carboxyl groups they carry. Which of the following is a basic amino acid?","image":"","options":["Glutamic acid","Valine","Lysine","Tyrosine"],"optionsInImage":false,"answer":["3"],"explanation":"Lysine is the basic amino acid in this list. Glutamic acid is acidic, valine is neutral, and tyrosine is classified as aromatic.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-137","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":137,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A diagram shows a single long polypeptide chain folded upon itself like a hollow woollen ball. Hydrogen bonds and disulphide bonds are labelled holding the folds together, and no other chain is present. This diagram represents which level of protein structure?","image":"","options":["Primary","Secondary","Tertiary","Quaternary"],"optionsInImage":false,"answer":["3"],"explanation":"Folding of a single chain upon itself into a 3D ball-like shape is tertiary structure. Quaternary structure needs more than one subunit, and secondary structure refers to local helices or sheets.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-138","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":138,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Cellulose does not give a blue colour when treated with iodine.\nReason (R): Cellulose does not contain complex helices and therefore cannot hold $I_2$ molecules.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"The blue colour comes from $I_2$ held inside the helical portion of starch. Cellulose lacks complex helices, so it cannot hold iodine and stays uncoloured. R therefore directly explains A.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-139","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":139,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the following elements: H, C, O, N, S, Na, Ca, Mg, Si.\nUsing NCERT's Table 9.1, how many of these have a higher percentage by weight in the human body than in the earth's crust?","image":"","options":["3","4","5","6"],"optionsInImage":false,"answer":["3"],"explanation":"H (9.5 vs 0.14), C (18.5 vs 0.03), O (65.0 vs 46.6), N (3.3 vs very little) and S (0.3 vs 0.03) are higher in the human body, giving five. Na, Ca, Mg and Si are more abundant in the crust.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-140","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":140,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): A protein is a heteropolymer.\nReason (R): Only some portions of a protein thread are folded in the form of a helix.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["2"],"explanation":"A protein is a heteropolymer because it is built from different types of amino acids. Partial helical folding is also true, but it concerns secondary structure and does not explain why the monomers differ.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-141","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":141,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"$\\alpha$-amino acids are described as substituted methanes. The four groups that occupy the four valencies of the $\\alpha$-carbon are:","image":"","options":["Hydrogen, carboxyl group, amino group and R group","Hydrogen, hydroxyl group, amino group and R group","Two hydrogens, carboxyl group and amino group in all amino acids","Carboxyl group, amino group, phosphate group and R group"],"optionsInImage":false,"answer":["1"],"explanation":"The $\\alpha$-carbon carries H, $-COOH$, $-NH_2$ and a variable R group, so the amino and acidic groups sit on the same carbon. Two hydrogens are present only in glycine, because its R group is itself a hydrogen. That is not a general rule.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-142","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":142,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: All the elements present in a sample of earth's crust are also present in a sample of living tissue.\nStatement II: Sodium, calcium and magnesium have a higher percentage by weight in the human body than in the earth's crust.\nChoose the correct option.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["2"],"explanation":"Qualitatively, the two element lists do not differ, so Statement I is correct. Na (2.8 vs 0.2), Ca (3.6 vs 1.5) and Mg (2.1 vs 0.1) are actually more abundant in the earth's crust, so Statement II is incorrect.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-143","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":143,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In which of the following pairs do BOTH compounds belong to the same category of secondary metabolites as given in NCERT?","image":"","options":["Ricin and Concanavalin A","Codeine and Curcumin","Carotenoids and Anthocyanins","Rubber and Lemon grass oil"],"optionsInImage":false,"answer":["3"],"explanation":"Carotenoids and anthocyanins are both pigments. Each of the other pairs mixes two categories: ricin is a toxin but concanavalin A is a lectin; codeine is an alkaloid but curcumin is a drug; rubber is a polymeric substance but lemon grass oil is an essential oil.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-144","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":144,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Three proteinaceous amino acids, X, Y and Z, differ only in their R groups:\nX: the R group carries an additional carboxyl group\nY: the R group carries an additional amino group\nZ: the R group is a methyl group\nBased on the number of amino and carboxyl groups, X, Y and Z would respectively be classified as:","image":"","options":["Basic, acidic, aromatic","Acidic, basic, neutral","Neutral, basic, acidic","Acidic, neutral, aromatic"],"optionsInImage":false,"answer":["2"],"explanation":"An extra carboxyl group makes X acidic, like glutamic acid. An extra amino group makes Y basic, like lysine. A methyl R group gives alanine, which has one amino and one carboxyl group and is therefore neutral, not aromatic.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-145","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":145,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Malonate acts as a competitive inhibitor of succinic dehydrogenase because its structure closely resembles that of the enzyme succinic dehydrogenase.\nStatement II: Once all enzyme molecules are saturated with substrate, further increase in substrate concentration does not raise the reaction velocity beyond $V_{max}$.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["4"],"explanation":"Malonate resembles the substrate succinate, not the enzyme, and so competes for the substrate-binding site. Statement I is therefore incorrect. Statement II is correct: enzyme molecules are fewer than substrate molecules, so after saturation no free enzyme is left and velocity plateaus at $V_{max}$.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-146","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":146,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The rate of a process is defined as $\\frac{\\delta P}{\\delta t}$. According to the general rule of thumb, how does this rate change when the temperature is raised by 10°C?","image":"","options":["It falls to half","It roughly doubles","It increases ten times","It remains unchanged"],"optionsInImage":false,"answer":["2"],"explanation":"The rule of thumb is that rate roughly doubles for every 10°C rise and roughly halves for every 10°C fall. The tenfold option confuses the 10°C step with the size of the change.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-147","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":147,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A student weighs a fresh leaf, dries it completely and weighs it again. The student then burns the dried material fully. Which of the following statements about this analysis is INCORRECT?","image":"","options":["The difference between the wet weight and the dry weight mainly represents the water content of the leaf.","On complete burning, the carbon compounds are oxidised to $CO_2$ and water vapour, which escape.","The ash left behind contains inorganic elements such as calcium and magnesium.","Inorganic compounds such as sulphate and phosphate appear in the acid-insoluble fraction, not in the acid-soluble fraction."],"optionsInImage":false,"answer":["4"],"explanation":"NCERT states that inorganic compounds such as $SO_4^{2-}$ and $PO_4^{3-}$ are seen in the acid-soluble fraction, so option 4 is wrong. The acid-insoluble fraction holds the macromolecules: proteins, nucleic acids, polysaccharides and membrane lipids. The other three statements correctly describe wet weight, dry weight and ash.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-148","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":148,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Consider the following elements:\nHydrogen, Carbon, Oxygen, Sodium, Calcium, Magnesium, Silicon, Sulphur\nHow many of these have a higher percentage by weight in the earth's crust than in the human body?","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["3"],"explanation":"Four elements are more abundant in the crust: sodium (2.8 vs 0.2), calcium (3.6 vs 1.5), magnesium (2.1 vs 0.1) and silicon (27.7 vs negligible). Hydrogen, carbon, oxygen and sulphur are all higher in the human body. Oxygen is the trap: although it is about 46.6% of the crust, it makes up 65% of the body.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-149","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":149,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Palmitic acid, a common fatty acid, contains how many carbon atoms in total, including the carboxyl carbon?","image":"","options":["14","16","18","20"],"optionsInImage":false,"answer":["2"],"explanation":"Palmitic acid has 16 carbons when the carboxyl carbon is counted. Twenty carbons is the count for arachidonic acid.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-150","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":150,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (amino acid) with List-II (category).\nList-I:\n(A) Glutamic acid\n(B) Lysine\n(C) Valine\n(D) Tryptophan\nList-II:\n(I) Neutral\n(II) Aromatic\n(III) Acidic\n(IV) Basic\nChoose the correct option.","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-IV, C-II, D-I","A-I, B-IV, C-III, D-II"],"optionsInImage":false,"answer":["1"],"explanation":"Glutamic acid is acidic, lysine is basic, valine is neutral and tryptophan is aromatic. The usual trap is mixing up glutamic acid (acidic) with lysine (basic).","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-151","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":151,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The most abundant component of living organisms is","image":"","options":["Protein","Water","Sugar","Nucleic acid"],"optionsInImage":false,"answer":["2"],"explanation":"Water is the most abundant chemical in living organisms. It makes up about 70–90% of total cellular mass.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q8)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-152","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":152,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Given below are two statements:\nStatement I: Collagen is the most abundant protein in the whole of the biosphere.\nStatement II: Ribulose bisphosphate carboxylase-oxygenase (RuBisCO) is the most abundant protein in the whole of the biosphere.\nChoose the correct answer.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["4"],"explanation":"Collagen is the most abundant protein in the animal world, not in the whole biosphere. RuBisCO holds the title for the entire biosphere.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-153","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":153,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Beyond a certain point, increasing the substrate concentration does not raise the velocity of an enzyme-catalysed reaction above $V_{max}$.\nReason (R): The enzyme molecules are fewer than the substrate molecules, and once they are saturated no free enzyme is left to bind the extra substrate.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["1"],"explanation":"Once every enzyme molecule is occupied, adding more substrate cannot form more ES complexes, so the velocity plateaus at $V_{max}$. Saturation of the limited enzyme molecules therefore directly explains the assertion.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-154","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":154,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: The acid-soluble pool represents roughly the cytoplasmic composition of a cell.\nStatement II: Like polysaccharides, lipids have molecular weights of ten thousand daltons and above.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"The acid-soluble pool does roughly reflect cytoplasmic composition. Lipids, however, are the exception among acid-insoluble compounds, with molecular weights not exceeding about 800 Da.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-155","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":155,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are secondary metabolites?\nMorphine, Concanavalin A, Glycine, Ricin, Carotenoids, Lecithin, Curcumin, Vinblastin","image":"","options":["4","5","6","7"],"optionsInImage":false,"answer":["3"],"explanation":"Six are secondary metabolites: morphine (alkaloid), concanavalin A (lectin), ricin (toxin), carotenoids (pigment), and curcumin and vinblastin (drugs). Glycine (an amino acid) and lecithin (a phospholipid) are primary metabolites with known physiological roles.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-156","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":156,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"An amino acid is dissolved in water and the pH is then varied. Which of the following correctly describes its zwitterionic form?","image":"","options":["$H_2N-CH(R)-COOH$, carrying no charged group","$^{+}H_3N-CH(R)-COOH$, carrying a net positive charge","$^{+}H_3N-CH(R)-COO^{-}$, carrying both a positive and a negative charge with no net charge","$H_2N-CH(R)-COO^{-}$, carrying a net negative charge"],"optionsInImage":false,"answer":["3"],"explanation":"In the zwitterion the amino group is protonated ($-NH_3^+$) and the carboxyl group is ionised ($-COO^-$) on the same molecule, so the net charge is zero. The fully protonated form predominates in acidic solution and the anionic form in basic solution.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-157","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":157,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"When iodine solution is added to a sample, a blue colour develops. Which polysaccharide is most likely present?","image":"","options":["Cellulose","Chitin","Starch","Inulin"],"optionsInImage":false,"answer":["3"],"explanation":"Starch forms helical secondary structures that can hold $I_2$ molecules, and the starch-iodine complex is blue. Cellulose lacks such complex helices, so it gives no blue colour.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-158","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":158,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements is INCORRECT?","image":"","options":["The acid-insoluble fraction contains only four types of organic compounds.","Biomolecules with molecular weights below one thousand daltons are called micromolecules.","Lipids, together with polysaccharides, polypeptides and nucleic acids, form the true macromolecular fraction of a cell.","Carbohydrates and lipids together account for roughly 5% of the total cellular mass."],"optionsInImage":false,"answer":["3"],"explanation":"Only polysaccharides, polypeptides and nucleic acids form the true macromolecular fraction; lipids are not strictly macromolecules. The last statement is correct because carbohydrates (3%) and lipids (2%) add up to about 5%.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-159","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":159,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: A protein consisting of only a single polypeptide chain cannot have a quaternary structure.\nStatement II: If the order of amino acids in a polypeptide is changed without changing which amino acids are present or how many, its primary structure changes.","image":"","options":["Both Statement I and Statement II are correct","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct","Both Statement I and Statement II are incorrect"],"optionsInImage":false,"answer":["1"],"explanation":"Quaternary structure is the arrangement of two or more subunits, so a single-chain protein cannot have it. Primary structure is positional information, so rearranging the same amino acids changes it even though the composition stays the same.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-160","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":160,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following are nucleotides?\nAdenosine, guanylic acid, thymidine, cytidylic acid, uracil, uridylic acid","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Guanylic acid, cytidylic acid and uridylic acid carry a phosphate esterified to the sugar, so they are nucleotides. Adenosine and thymidine are nucleosides, and uracil is a free base.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-161","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":161,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A nitrogenous base attached to a sugar, without any phosphate group, is called a nucleoside. Which of the following is a nucleoside?","image":"","options":["Uridylic acid","Uridine","Uracil","Ribose"],"optionsInImage":false,"answer":["2"],"explanation":"Uridine is uracil joined to a sugar, so it is a nucleoside. Uridylic acid also carries a phosphate and is a nucleotide; uracil is only the base and ribose is only the sugar.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-162","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":162,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about co-factors are correct?\n(i) Prosthetic groups are organic compounds tightly bound to the apoenzyme.\n(ii) Haem is the prosthetic group of peroxidase and catalase.\n(iii) Co-enzymes remain permanently bound to the apoenzyme, even when no catalysis is occurring.\n(iv) NAD and NADP contain the vitamin niacin.\n(v) Zinc is a metal ion co-factor for carboxypeptidase.","image":"","options":["3","4","5","2"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (i), (ii), (iv) and (v) are correct, giving four. Statement (iii) is wrong because a co-enzyme associates with the apoenzyme only transiently, usually during catalysis; tight binding is the defining feature of prosthetic groups.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-163","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":163,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In a protein molecule, the amino acids are joined to one another in a linear chain by which type of bond?","image":"","options":["Glycosidic bond","Peptide bond","Phosphodiester bond","Ester bond"],"optionsInImage":false,"answer":["2"],"explanation":"Proteins are polypeptides, which are linear chains of amino acids linked by peptide bonds. Glycosidic bonds link sugars, phosphodiester bonds link nucleotides, and ester bonds link fatty acids to glycerol.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-164","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":164,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Enzymes are divided into 6 classes, each with 4–13 subclasses, and are named by a four-digit number.\nStatement II: Enzymes that catalyse hydrolysis of peptide and glycosidic bonds are placed in the class lyases.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Statement I correctly describes the classification system. Hydrolysis of ester, ether, peptide, glycosidic and similar bonds is carried out by hydrolases. Lyases remove groups by mechanisms other than hydrolysis.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-165","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":165,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The following events of an enzyme's catalytic cycle are given in jumbled order:\nP. The active site breaks chemical bonds of the substrate and an enzyme-product complex forms\nQ. The substrate binds to and fits into the active site\nR. The free enzyme releases the products and is ready for another substrate molecule\nS. Substrate binding induces the enzyme to alter its shape and fit more tightly around the substrate\nChoose the correct sequence:","image":"","options":["Q, P, S, R","Q, S, P, R","S, Q, P, R","Q, S, R, P"],"optionsInImage":false,"answer":["2"],"explanation":"The cycle runs as E + S → ES → EP → E + P. The substrate first binds (Q). This binding then induces the enzyme to change shape and fit more tightly (S), which is the induced-fit step. Next, bonds are broken and an EP complex forms (P), and finally the product is released (R). Placing the shape change after bond breaking, or before binding, is the trap.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-166","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":166,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I\nA. Palmitic acid\nB. Arachidonic acid\nC. Lecithin\nD. Gingelly oil\nList-II\nI. Phospholipid found in cell membranes\nII. 20 carbon atoms including the carboxyl carbon\nIII. Glyceride with low melting point that stays liquid in winter\nIV. 16 carbon atoms including the carboxyl carbon\nChoose the correct answer:","image":"","options":["A-IV, B-II, C-I, D-III","A-II, B-IV, C-I, D-III","A-IV, B-II, C-III, D-I","A-II, B-IV, C-III, D-I"],"optionsInImage":false,"answer":["1"],"explanation":"Palmitic acid has 16 carbons and arachidonic acid has 20 carbons, both counts including the carboxyl carbon. Lecithin is a membrane phospholipid, and gingelly oil is an oil because its low melting point keeps it liquid in winter. The common trap is swapping the carbon counts of the two fatty acids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-167","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":167,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following statements about lipids are correct?\n(i) In a fatty acid, the R group attached to the carboxyl group may contain 1 to 19 carbon atoms.\n(ii) In palmitic acid, $CH_3(CH_2)_{14}COOH$, the R group contains 15 carbon atoms.\n(iii) A triglyceride has three fatty acid molecules esterified to one glycerol molecule.\n(iv) Lipids are true macromolecules, which is why they separate into the acid-insoluble fraction.\n(v) Unsaturated fatty acids are those that lack C=C double bonds.","image":"","options":["2","3","4","5"],"optionsInImage":false,"answer":["2"],"explanation":"Statements (i), (ii) and (iii) are correct; in palmitic acid, 1 CH3 plus 14 CH2 gives 15 carbons in R, plus the carboxyl carbon for 16 in total. Statement (iv) is wrong because lipids are small molecules (below 800 Da) that land in the acid-insoluble fraction only as membrane vesicles. Statement (v) is wrong because unsaturated fatty acids contain one or more C=C bonds.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-168","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":168,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"In the amino acid serine, the variable R group attached to the $\\alpha$-carbon is:","image":"","options":["A hydrogen atom","A methyl group","A hydroxymethyl group","An aromatic ring"],"optionsInImage":false,"answer":["3"],"explanation":"Serine carries a hydroxymethyl ($-CH_2OH$) group as its R group. Glycine has hydrogen and alanine has a methyl group, so those options are common mix-ups.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-169","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":169,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which one of the following is an aromatic amino acid?","image":"","options":["Valine","Tryptophan","Lysine","Glutamic acid"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT lists tyrosine, phenylalanine and tryptophan as aromatic amino acids. Valine is neutral, lysine is basic and glutamic acid is acidic.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-170","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":170,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Morphine and codeine are secondary metabolites. In which category of secondary metabolites are they placed?","image":"","options":["Terpenoids","Alkaloids","Lectins","Toxins"],"optionsInImage":false,"answer":["2"],"explanation":"NCERT lists morphine and codeine as examples of alkaloids. Abrin and ricin are the toxins, concanavalin A is a lectin, and monoterpenes and diterpenes are terpenoids.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-171","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":171,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II.\nList-I (Amino acid)\nA. Glutamic acid\nB. Lysine\nC. Valine\nD. Phenylalanine\nList-II (Category)\nI. Neutral\nII. Aromatic\nIII. Acidic\nIV. Basic\nChoose the correct answer:","image":"","options":["A-III, B-IV, C-I, D-II","A-IV, B-III, C-I, D-II","A-III, B-IV, C-II, D-I","A-I, B-IV, C-III, D-II"],"optionsInImage":false,"answer":["1"],"explanation":"Glutamic acid is acidic, lysine is basic, valine is neutral and phenylalanine is aromatic. Students often swap glutamic acid and lysine, and that swap gives the second option.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-172","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":172,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements about nucleic acids is incorrect?","image":"","options":["A nucleotide consists of a heterocyclic nitrogen base, a monosaccharide and a phosphate","Uracil is a substituted purine found in RNA","The nucleic acid containing 2' deoxyribose is called DNA","Adenine and guanine are substituted purines"],"optionsInImage":false,"answer":["2"],"explanation":"Uracil, like cytosine and thymine, is a substituted pyrimidine. Only adenine and guanine are purines. The other three statements agree with NCERT.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-173","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":173,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (level of protein structure) with List-II (description) and choose the correct option.\nList-I\nA. Primary structure\nB. Secondary structure\nC. Tertiary structure\nD. Quaternary structure\nList-II\n(i) Arrangement of individual folded polypeptides or subunits with respect to one another\n(ii) Positional information, that is, which amino acid comes first, second and so on\n(iii) The long chain folded upon itself like a hollow woollen ball\n(iv) Some portions of the thread folded like a revolving staircase","image":"","options":["A-(ii), B-(iv), C-(iii), D-(i)","A-(ii), B-(iii), C-(iv), D-(i)","A-(i), B-(iv), C-(iii), D-(ii)","A-(iv), B-(ii), C-(i), D-(iii)"],"optionsInImage":false,"answer":["1"],"explanation":"Primary structure is the amino acid sequence. Secondary structure is local folding such as the helix, which resembles a revolving staircase. Tertiary structure is the woollen-ball folding of the whole chain, and quaternary structure is the arrangement of subunits. The common trap is swapping the descriptions of the helix and the woollen ball.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-174","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":174,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Statement I: Inulin is a polysaccharide made of fructose units.\nStatement II: In a glycogen chain, the right end is called the non-reducing end and the left end is called the reducing end.","image":"","options":["Both Statement I and Statement II are correct","Both Statement I and Statement II are incorrect","Statement I is correct but Statement II is incorrect","Statement I is incorrect but Statement II is correct"],"optionsInImage":false,"answer":["3"],"explanation":"Inulin is a polymer of fructose, so Statement I is correct. In a polysaccharide chain such as glycogen, the right end is the reducing end and the left end is the non-reducing end, so Statement II has the two ends swapped.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-175","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":175,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Enzymes are biocatalysts. They catalyse biochemical reactions. In general they reduce activation energy of reactions. Many physico-chemical processes are enzyme mediated. Which of the following reactions is not enzyme-mediated in biological system?","image":"","options":["Dissolving CO$_2$ in water","Untwining the two strands of DNA","Hydrolysis of sucrose","Formation of peptide bond"],"optionsInImage":false,"answer":["1"],"explanation":"Simply dissolving CO$_2$ in water is a physical process and needs no enzyme. Unwinding DNA (helicase), hydrolysis of sucrose (invertase) and peptide bond formation (peptidyl transferase) are all enzyme-catalysed.","source":"practice-ncert","credit":"Source: NCERT Exemplar Biology Class 11, Ch 9 (MCQ Q14)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-176","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":176,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A nucleotide is built from three chemically distinct components. Which of the following is NOT one of them?","image":"","options":["A heterocyclic nitrogenous base","A pentose monosaccharide","Phosphoric acid (phosphate)","Glycerol"],"optionsInImage":false,"answer":["4"],"explanation":"A nucleotide consists of a heterocyclic base, a monosaccharide sugar and a phosphate. Glycerol is a component of glycerides and phospholipids, not of nucleotides.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-177","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":177,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Adult human haemoglobin is made up of:","image":"","options":["Two subunits, one of $\\alpha$ type and one of $\\beta$ type","Four identical $\\alpha$ subunits","Four subunits: three of $\\alpha$ type and one of $\\beta$ type","Four subunits: two of $\\alpha$ type and two of $\\beta$ type"],"optionsInImage":false,"answer":["4"],"explanation":"Adult human haemoglobin has 4 subunits, made up of two $\\alpha$ type and two $\\beta$ type. The subunits are identical only in pairs, not all four.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-178","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":178,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (enzyme class) with List-II (type of reaction catalysed):\nList-I\nA. Transferases\nB. Lyases\nC. Isomerases\nD. Ligases\nList-II\nI. Inter-conversion of optical, geometric or positional isomers\nII. Linking together of two compounds, e.g., forming C–N or P–O bonds\nIII. Transfer of a group other than hydrogen between a pair of substrates\nIV. Removal of groups by mechanisms other than hydrolysis, leaving double bonds\nChoose the correct answer:","image":"","options":["A-III, B-IV, C-I, D-II","A-III, B-II, C-I, D-IV","A-IV, B-III, C-II, D-I","A-II, B-IV, C-III, D-I"],"optionsInImage":false,"answer":["1"],"explanation":"Transferases move a group G (not hydrogen) from S to S'. Lyases remove groups non-hydrolytically and leave double bonds. Isomerases interconvert isomers, and ligases join two compounds together.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-179","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":179,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which of the following statements is INCORRECT?","image":"","options":["Adenine and guanine are substituted purines, whereas cytosine, uracil and thymine are substituted pyrimidines.","Removing the phosphate group from adenylic acid would leave adenosine.","Lipids, polysaccharides and nucleic acids together constitute the true macromolecular fraction of a cell.","DNA and RNA both consist of nucleotides only and function as genetic material."],"optionsInImage":false,"answer":["3"],"explanation":"The true macromolecular fraction consists of polysaccharides, polypeptides (proteins) and nucleic acids. Lipids appear in the acid-insoluble fraction only because membrane fragments form vesicles; they are not strictly macromolecules.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"hard"},{"id":"NCERT11-BIO-BIOMOLECULES-180","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":180,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Assertion (A): Enzymes isolated from organisms living in hot vents and sulphur springs can retain catalytic activity at 80°–90°C.\nReason (R): Low temperature permanently destroys enzyme activity by denaturing the protein.","image":"","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"optionsInImage":false,"answer":["3"],"explanation":"Enzymes from thermophilic organisms are thermally stable, so A is true. Low temperature only keeps an enzyme in a temporarily inactive state; it is high temperature that denatures proteins. R is therefore false.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-181","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":181,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"How many of the following amino acids are aromatic?\nTyrosine, Valine, Phenylalanine, Serine, Tryptophan, Alanine, Lysine, Glycine","image":"","options":["Two","Three","Four","Five"],"optionsInImage":false,"answer":["2"],"explanation":"Only tyrosine, phenylalanine and tryptophan are aromatic. Valine, serine, alanine, lysine and glycine have non-aromatic R groups.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-182","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":182,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"A biomolecule is made of the nitrogen base uracil attached to a ribose sugar, with no phosphate group. This molecule is best described as a:","image":"","options":["Nitrogenous base","Nucleotide","Nucleoside","Polynucleotide"],"optionsInImage":false,"answer":["3"],"explanation":"A nitrogen base attached to a sugar is a nucleoside. This one is uridine. It becomes a nucleotide only when a phosphate is esterified to the sugar.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-183","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":183,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I (enzyme class) with List-II (type of reaction catalysed):\nList-I\nA. Oxidoreductases\nB. Transferases\nC. Lyases\nD. Ligases\nList-II\n(i) Joining two compounds, forming C–O, C–S, C–N or P–O bonds\n(ii) Removal of groups by mechanisms other than hydrolysis, leaving double bonds\n(iii) Transfer of a group other than hydrogen between a pair of substrates\n(iv) Oxidoreduction between two substrates S and S'","image":"","options":["A-(iii), B-(iv), C-(i), D-(ii)","A-(iv), B-(iii), C-(ii), D-(i)","A-(iv), B-(iii), C-(i), D-(ii)","A-(ii), B-(iii), C-(iv), D-(i)"],"optionsInImage":false,"answer":["2"],"explanation":"Oxidoreductases carry out redox reactions between two substrates, and transferases move a non-hydrogen group. Lyases remove groups without hydrolysis, leaving double bonds, while ligases join two compounds. The usual trap is swapping lyases (removal) with ligases (joining).","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-184","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":184,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Match List-I with List-II:\nList-I\n(A) Palmitic acid\n(B) Arachidonic acid\n(C) Glycerol\n(D) Lecithin\nList-II\n(I) Phospholipid\n(II) 20 carbon atoms including carboxyl carbon\n(III) Trihydroxy propane\n(IV) 16 carbon atoms including carboxyl carbon","image":"","options":["A-IV, B-II, C-III, D-I","A-II, B-IV, C-III, D-I","A-IV, B-II, C-I, D-III","A-III, B-IV, C-II, D-I"],"optionsInImage":false,"answer":["1"],"explanation":"Palmitic acid has 16 carbons and arachidonic acid has 20. Glycerol is trihydroxy propane, and lecithin is a phospholipid. Mixing up the carbon counts of the two fatty acids is the usual trap.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"medium"},{"id":"NCERT11-BIO-BIOMOLECULES-185","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":185,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"Which chemical makes up the largest share of the total mass of a cell?","image":"","options":["Proteins","Nucleic acids","Water","Carbohydrates"],"optionsInImage":false,"answer":["3"],"explanation":"Water makes up 70-90% of the total cellular mass, so it is the most abundant chemical in living organisms. Proteins come next at 10-15%.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"},{"id":"NCERT11-BIO-BIOMOLECULES-186","exam":"NEET","year":null,"paper":"Practice · Biomolecules","qno":186,"subject":"Biology","section":"","part":"","chapter":"Biomolecules","type":"mcq","question":"The proteolytic enzyme carboxypeptidase needs which cofactor for its activity?","image":"","options":["Haem as a prosthetic group","Zinc as a metal ion","NAD as a coenzyme","Niacin as a prosthetic group"],"optionsInImage":false,"answer":["2"],"explanation":"Zinc is the metal ion cofactor of carboxypeptidase. It forms coordination bonds with side chains at the active site and with the substrate. Haem is the prosthetic group of peroxidase and catalase, not of carboxypeptidase.","source":"practice-ncert","credit":"SONEXA original (NCERT-based)","basis":"NCERT Class 11 Biology, Ch 9 · Biomolecules","difficulty":"easy"}]});
